        const btn=button(label);btn.dataset.syncAll=choice;
        btn.onclick=()=>{for(const row of conflicts)if(!row.allowedSides || row.allowedSides.includes(choice))decisions[row.key]=choice;draw();};
        bulk.append(btn);
